    <script>
        // ---------- theme ----------
        const toggleTheme = () => {
            const html = document.documentElement;
            const isDark = html.getAttribute('data-theme') === 'dark';
            html.setAttribute('data-theme', isDark ? 'light' : 'dark');
            localStorage.setItem('owl-theme', isDark ? 'light' : 'dark');
        };
        // restore saved
        const saved = localStorage.getItem('owl-theme');
        if (saved) document.documentElement.setAttribute('data-theme', saved);

        // ---------- nav ----------
        const switchNav = (el) => {
            document.querySelectorAll('.nav-item').forEach(i => i.classList.remove('active'));
            el.classList.add('active');
        };

        // ---------- tab ----------
        const switchTab = (el, period) => {
            document.querySelectorAll('.chart-tab').forEach(t => t.classList.remove('active'));
            el.classList.add('active');
            drawChart(period);
        };

        // ---------- chart (pure canvas) ----------
        const canvas = document.getElementById('aiChart');
        const ctx = canvas.getContext('2d');

        function resizeCanvas() {
            const dpr = window.devicePixelRatio || 1;
            const rect = canvas.parentElement.getBoundingClientRect();
            canvas.width = rect.width * dpr;
            canvas.height = 300 * dpr;
            canvas.style.width = rect.width + 'px';
            canvas.style.height = '300px';
            ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        }

        const datasets = {
            '7d': {
                labels: ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],
                actual: [4200, 4800, 4500, 5100, 5600, 6200, 5900],
                predicted: [4000, 4700, 4600, 5000, 5500, 6000, 5800]
            },
            '30d': {
                labels: ['W1','W2','W3','W4'],
                actual: [28000, 31000, 29500, 33000],
                predicted: [27500, 30000, 30000, 32000]
            },
            '90d': {
                labels: ['Jan','Feb','Mar'],
                actual: [110000, 125000, 138000],
                predicted: [108000, 122000, 135000]
            }
        };

        function drawChart(period = '7d') {
            resizeCanvas();
            const { labels, actual, predicted } = datasets[period];
            const W = canvas.width / (window.devicePixelRatio || 1);
            const H = 300;
            const pad = { top: 30, right: 30, bottom: 50, left: 60 };
            const chartW = W - pad.left - pad.right;
            const chartH = H - pad.top - pad.bottom;

            const allVals = [...actual, ...predicted];
            const maxVal = Math.max(...allVals) * 1.15;
            const minVal = 0;

            const getX = (i) => pad.left + (i / (labels.length - 1)) * chartW;
            const getY = (v) => pad.top + chartH - ((v - minVal) / (maxVal - minVal)) * chartH;

            // clear
            ctx.clearRect(0, 0, W, H);

            // grid
            ctx.strokeStyle = getComputedStyle(document.body).getPropertyValue('--border').trim();
            ctx.lineWidth = 1;
            const gridLines = 5;
            for (let i = 0; i <= gridLines; i++) {
                const y = pad.top + (i / gridLines) * chartH;
                ctx.beginPath();
                ctx.moveTo(pad.left, y);
                ctx.lineTo(W - pad.right, y);
                ctx.stroke();

                // y-axis labels
                const val = Math.round(maxVal - (i / gridLines) * maxVal);
                ctx.fillStyle = getComputedStyle(document.body).getPropertyValue('--text-muted').trim();
                ctx.font = '12px Inter, sans-serif';
                ctx.textAlign = 'right';
                ctx.fillText(val.toLocaleString(), pad.left - 10, y + 4);
            }

            // x-axis labels
            ctx.textAlign = 'center';
            labels.forEach((label, i) => {
                const x = getX(i);
                ctx.fillText(label, x, H - pad.bottom + 20);
            });

            // gradient fills
            const isDark = document.documentElement.getAttribute('data-theme') === 'dark';

            function drawArea(data, colorStart, colorEnd) {
                const gradient = ctx.createLinearGradient(0, pad.top, 0, pad.top + chartH);
                gradient.addColorStop(0, colorStart);
                gradient.addColorStop(1, colorEnd);

                ctx.beginPath();
                ctx.moveTo(getX(0), getY(data[0]));
                // smooth curve
                for (let i = 0; i < data.length - 1; i++) {
                    const xMid = (getX(i) + getX(i + 1)) / 2;
                    const yMid = (getY(data[i]) + getY(data[i + 1])) / 2;
                    ctx.quadraticCurveTo(getX(i), getY(data[i]), xMid, yMid);
                }
                ctx.lineTo(getX(data.length - 1), getY(data[data.length - 1]));
                ctx.lineTo(getX(data.length - 1), pad.top + chartH);
                ctx.lineTo(getX(0), pad.top + chartH);
                ctx.closePath();
                ctx.fillStyle = gradient;
                ctx.fill();
            }

            drawArea(predicted, isDark ? 'rgba(0,206,201,.15)' : 'rgba(0,206,201,.12)', 'rgba(0,206,201,0)');
            drawArea(actual, isDark ? 'rgba(108,92,231,.25)' : 'rgba(108,92,231,.15)', 'rgba(108,92,231,0)');

            // lines
            function drawLine(data, color) {
                ctx.beginPath();
                ctx.moveTo(getX(0), getY(data[0]));
                for (let i = 0; i < data.length - 1; i++) {
                    const xMid = (getX(i) + getX(i + 1)) / 2;
                    const yMid = (getY(data[i]) + getY(data[i + 1])) / 2;
                    ctx.quadraticCurveTo(getX(i), getY(data[i]), xMid, yMid);
                }
                ctx.lineTo(getX(data.length - 1), getY(data[data.length - 1]));
                ctx.strokeStyle = color;
                ctx.lineWidth = 3;
                ctx.stroke();

                // dots
                data.forEach((v, i) => {
                    ctx.beginPath();
                    ctx.arc(getX(i), getY(v), 5, 0, Math.PI * 2);
                    ctx.fillStyle = color;
                    ctx.fill();
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 2;
                    ctx.stroke();
                });
            }

            drawLine(actual, '#6c5ce7');
            drawLine(predicted, '#00cec9');

            // legend
            const legendY = 15;
            ctx.font = '12px Inter, sans-serif';
            ctx.textAlign = 'left';

            ctx.fillStyle = '#6c5ce7';
            ctx.fillRect(pad.left, legendY - 8, 16, 10);
            ctx.fillStyle = getComputedStyle(document.body).getPropertyValue('--text').trim();
            ctx.fillText('Actual', pad.left + 22, legendY);

            ctx.fillStyle = '#00cec9';
            ctx.fillRect(pad.left + 80, legendY - 8, 16, 10);
            ctx.fillStyle = getComputedStyle(document.body).getPropertyValue('--text').trim();
            ctx.fillText('AI Predicted', pad.left + 98, legendY);
        }

        // init
        drawChart();

        // responsive redraw
        window.addEventListener('resize', () => drawChart());

        // ---------- live counter animation ----------
        const animateValue = (id, start, end, suffix = '', duration = 2000) => {
            const obj = document.getElementById(id);
            const range = end - start;
            const startTime = performance.now();
            const step = (now) => {
                const progress = Math.min((now - startTime) / duration, 1);
                const eased = 1 - Math.pow(1 - progress, 3);
                const current = Math.round(start + range * eased);
                obj.textContent = current.toLocaleString() + suffix;
                if (progress < 1) requestAnimationFrame(step);
            };
            requestAnimationFrame(step);
        };

        setTimeout(() => {
            animateValue('stat-users', 0, 24521);
            animateValue('stat-revenue', 0
